(3, '김미경소아과의원', '의원', FALSE, '02-355-8234', '02-2260-7414', '서울특별시 은평구 진흥로 150, 2층 (녹번동)', 37.60864363, 126.9266432, '수액처치/상처소독/성인진료(감기)/안질환/', '안녕하세요. 김미경산부인과입니다. 항상 원칙을 어긋나지 않는 마음과 함께, 진정성 있는 진료로 다가서는 것을 최우선의 가치로 삼고 있습니다.', '대조시장 맞은편 성수약국2층'),
