(640, '행복한아이소아청소년과의원', '의원', FALSE, '02-427-8822', '02-2290-8284', '서울특별시 강동구 고덕로 133, 501호 (암사동)', 37.55525285, 127.1403472, '휴게시간 12:30~14:00(토요일 제외)', '안녕하세요. 저희한의원에서는 디스크, 협착증 등의 근골격계 관절질환을 추나, 약침, 매선 치료를 통해 진료하고 있으비롯 고혈압, 당뇨, 고지혈증 등의 대사성질환을 피를 맑게하는 해독을 통해 치료합니다. 점심시간은 오후 12시30분~ 오후2시 입니다. 이용에 참고바랍니다.', '롯데캐슬아파트 상가 내 위치'),
(641, '헬리오아이언소아청소년과의원', '의원', FALSE, '02-2038-0946', '02-2290-8284', '서울특별시 송파구 송파대로 345, 1A동 5층 5007호일부,5008호 (가락동, 헬리오시티)', 37.49978409, 127.1114975, '휴게시간 13:00~14:00 진료종료 30분 전 접수마감 공휴일 진료는 병원사정에 따라 변동될 수 있습니다.', '마라토너 의사입니다 두통, 어지러움, 자율신경계부터 척추, 관절 등 모든 통증에 대해 진료합니다', '강남역 3, 4번 출구 도보 1분'),
(642, '현엠앤엠소아청소년과의원', '의원', FALSE, '02-3422-1253', '02-2290-8284', '서울특별시 중랑구 신내로 82, 403호 (신내동, 금강프라자)', 37.60667443, 127.0955215, '휴게시간 13:00~14:00 매월 첫째 주 토요일 휴진', '내과/소아과/이비인후과/피부과 진료 수액, 백신접종', '중랑구청 사거리 맥도날드 맞은편 백세약국 4층'),
(643, '형운준소아청소년과의원', '의원', FALSE, '02-826-1661', '02-2290-8284', '서울특별시 동작구 장승배기로 119, 2층 (노량진동)', 37.50826933, 126.9398861, '휴게시간 13:00~14:00', '상처소독ㅇ/성인진료ㅇ/소아안질환ㅇ', '장승배기역 5번 출구 쪽 위치 2층'),
(644, '혜담소아청소년과의원', '의원', FALSE, '02-2636-1100', '02-2290-8284', '서울특별시 양천구 목동서로 67, 3층 (목동, 우성에펠타운)', 37.53642705, 126.8785251, '휴게시간 13:00~14:00(토요일 제외) 진료종료 30분 전 접수마감', '수액처치/상처소독/성인진료', '목독파리공원 옆 우성에펠타운 3층'),
(645, '혜림소아청소년과의원', '의원', FALSE, '02-491-4018', '02-2290-8284', '서울특별시 중랑구 면목로 415 (면목동)', 37.58904624, 127.0871855, '휴게시간 13:00~14:00(토요일 제외) 진료종료 30분 전 접수마감', '2월부터 진료시간 변경 예정이므로 방문전 전화확인 필요', '면목역 3번 출구'),
(646, '혜민병원', '종합병원', TRUE, '02-2049-9000', '02-2049-9119', '서울특별시 광진구 자양로 85 (자양동)', 37.53531566, 127.0836013, '휴게시간 13:00~14:00(토요일 제외) 진료종료 30분 전 접수마감', '24시간 전문의 진료가 가능한 서울 동북부 지역 거점병원입니다.', '2호선 구의역 4번출구 직진방향 5분 거리'),
(647, '혜민소아청소년과의원', '의원', FALSE, '02-482-8284', '02-2049-9119', '서울특별시 강동구 올림픽로 774, 2층 3호 (암사동)', 37.55020341, 127.1277949, '휴게시간 13:00~14:00', '24시간 전문의 진료가 가능한 서울 동북부 지역 거점병원입니다.', '암사역 1번 출구'),
